def solve(line: str):
    fields = []
    i = 0
    n = len(line)
    cur = []
    in_quote = False
    while i < n:
        ch = line[i]
        if in_quote:
            if ch == '"':
                # check for escaped quote
                if i + 1 < n and line[i+1] == '"':
                    cur.append('"')
                    i += 1  # skip next quote
                else:
                    in_quote = False
                # continue
            else:
                cur.append(ch)
        else:
            if ch == ',':
                fields.append(''.join(cur))
                cur = []
            elif ch == '"':
                in_quote = True
            else:
                cur.append(ch)
        i += 1
    # add last field
    fields.append(''.join(cur))
    return fields

