    Resolve '.' and empty components, handle '..' to go up one directory, collapse multiple slashes.
    Return '/' for the root.
    """
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            # if no stack, stay at root
        else:
            stack.append(part)
    return '/' + '/'.join(stack) if stack else '/'

