def solve(a, b):
    # classic DP O(len(a)*len(b))
    m, n = len(a), len(b)
    # Ensure the shorter string is b to use less memory if we implement row-wise
    # Here we use full matrix for clarity
    dp = [[0]*(n+1) for _ in range(m+1)]
    for i in range(m+1):
        dp[i][0] = i
    for j in range(n+1):
        dp[0][j] = j
    for i in range(1, m+1):
        for j in range(1, n+1):
            if a[i-1] == b[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(dp[i-1][j],   # deletion
                                   dp[i][j-1],   # insertion
                                   dp[i-1][j-1]) # substitution
    return dp[m][n]

