            continue
    for v in values:
        try:
            v_list.append(int(v))
        except Exception:
            continue
    # Ensure same length by truncating to the shorter list
    n = min(len(w_list), len(v_list))
    w_list = w_list[:n]
    v_list = v_list[:n]
    if capacity < 0:
        return 0
    dp = [0] * (capacity + 1)
    for w, v in zip(w_list, v_list):
        if w < 0:
            # negative weight would increase capacity; ignore as undefined
            continue
        # iterate backwards to enforce 0/1 usage
        for c in range(capacity, w - 1, -1):
            new_val = dp[c - w] + v
            if new_val > dp[c]:
                dp[c] = new_val
    return dp[capacity]

