code:
def solve(coins, amount):
    """Return the minimum number of coins required to make up *amount* using
    unlimited supply of each coin value in *coins*. If it is impossible, return -1.
    Implements classic bottom‑up DP with O(amount * len(coins)) time.
    """
    if amount < 0:
        return -1
    # DP array where dp[i] is min coins for amount i; use amount+1 as INF sentinel.
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                # If we can use coin c, consider dp[a - c] + 1.
                if dp[a - c] + 1 < dp[a]:
                    dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != INF else -1

