    Each item can be taken at most once.
    """
    if capacity <= 0 or not weights:
        return 0
    # DP array where dp[c] is max value for capacity c
    dp = [0] * (capacity + 1)
    for w, v in zip(weights, values):
        if w > capacity:
            # cannot fit, skip updating
            continue
        # iterate backwards to avoid reuse of the same item
        for c in range(capacity, w - 1, -1):
            new_val = dp[c - w] + v
            if new_val > dp[c]:
                dp[c] = new_val
    return dp[capacity]

