def solve(grid):
    """Count islands (connected components of 1s) in a grid.
    Handles empty grid, rows of varying lengths, and any truthy value as land.
    """
    if not grid:
        return 0
    n = len(grid)
    # Determine max columns to iterate safely; we will check each row's length
    visited = []
    for row in grid:
        visited.append([False] * len(row))
    def get_cell(i, j):
        return grid[i][j]
    def in_bounds(i, j):
        return 0 <= i < n and 0 <= j < len(grid[i])
    def dfs(i, j):
        stack = [(i, j)]
        visited[i][j] = True
        while stack:
            x, y = stack.pop()
            for dx, dy in [(1,0), (-1,0), (0,1), (0,-1)]:
                nx, ny = x + dx, y + dy
                if in_bounds(nx, ny) and not visited[nx][ny] and get_cell(nx, ny) == 1:
                    visited[nx][ny] = True
                    stack.append((nx, ny))
    count = 0
    for i in range(n):
        for j in range(len(grid[i])):
            if not visited[i][j] and grid[i][j] == 1:
                count += 1
                dfs(i, j)
    return count

