def solve(a, x):
    """Return leftmost insertion index for x in sorted sequence a.
    Works like bisect_left. Accepts any iterable for a.
    """
    # Convert a to list if it's not already a list for indexing.
    try:
        seq = list(a)
    except Exception:
        seq = []
    # Use binary search
    lo, hi = 0, len(seq)
    while lo < hi:
        mid = (lo + hi) // 2
        try:
            if seq[mid] < x:
                lo = mid + 1
            else:
                hi = mid
        except Exception:
            # If comparison fails, treat as not less
            hi = mid
    return lo

