def solve(matrix):
    """Return the determinant of a square matrix of integers.
    Uses the Bareiss fraction-free Gaussian elimination algorithm, which
    preserves integer arithmetic and runs in O(n^3). Works for empty matrix
    (determinant 1) and 1x1 matrices.
    """
    # Validate input is a list of lists and square
    if not matrix:
        # By convention, determinant of empty matrix is 1
        return 1
    n = len(matrix)
    for row in matrix:
        if len(row) != n:
            raise ValueError("Matrix must be square")
    # Make a copy to avoid mutating the input
    a = [list(map(int, row)) for row in matrix]
    det = 1
    for k in range(n - 1):
        # Find pivot; if zero, swap with a lower row
        if a[k][k] == 0:
            swap_row = None
            for i in range(k + 1, n):
                if a[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            a[k], a[swap_row] = a[swap_row], a[k]
            det = -det
        pivot = a[k][k]
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                # Bareiss update
                a[i][j] = (a[i][j] * pivot - a[i][k] * a[k][j]) // (a[k - 1][k - 1] if k > 0 else 1)
        # Zero out the column below pivot
        for i in range(k + 1, n):
            a[i][k] = 0
    det *= a[n - 1][n - 1]
    return det

